    observacoes: "REGISTRO MAIS AUSTRAL DA ESPÉCIE EM TODAS AS AMÉRICAS. Dentário de indivíduo juvenil, 217 mm. Eremotherium é comum na região intertropical do Brasil e tinha um único registro anterior no sul, em Caçapava do Sul, cerca de 400 km a noroeste. Distinguido de Megatherium pela sínfise que alcança o m1 e pelo processo angular projetado posteriormente. Coordenada aproximada: a fonte delimita o trecho fossilífero por dois extremos em UTM, a cerca de 19 km um do outro ao longo do arroio; adotado o ponto médio, conferido por ponto-em-polígono contra a malha do IBGE (cai em Santa Vitória do Palmar). O extremo oeste publicado cai fora do polígono municipal — provavelmente dentro da Lagoa Mirim. Idades por ressonância de spin eletrônico em dentes fósseis situam a assembleia entre ~226 e ~34 mil anos AP, um intervalo longo demais para uma única fauna — o conjunto pode ser tempo-médio.",
