    tipo_fonte: "Artigo em periódico", doi: "10.4072/rbp.2012.2.10",
    observacoes: "Oito galhadas, duas ainda presas a fragmentos de crânio. Menores que as de Antifer, com eixo levemente curvado em S. O espécime LGP-I 0005 é o único fóssil conhecido do arroio Chuí com concreções carbonáticas na superfície. Ozotoceros, citado em trabalhos antigos para o arroio, não foi confirmado. Coordenada aproximada: a fonte delimita o trecho fossilífero por dois extremos em UTM, a cerca de 19 km um do outro ao longo do arroio; adotado o ponto médio, conferido por ponto-em-polígono contra a malha do IBGE (cai em Santa Vitória do Palmar). O extremo oeste publicado cai fora do polígono municipal — provavelmente dentro da Lagoa Mirim. Idades por ressonância de spin eletrônico em dentes fósseis situam a assembleia entre ~226 e ~34 mil anos AP, um intervalo longo demais para uma única fauna — o conjunto pode ser tempo-médio.",
    citacao_abnt: "PEREIRA, J. C.; LOPES, R. P.; KERBER, L. New remains of Late Pleistocene mammals from the Chuí Creek, Southern Brazil. Revista Brasileira de Paleontologia, v. 15, n. 2, p. 228-239, 2012.",
