    observacoes: "Vizcacha. PRIMEIRO REGISTRO CONFIÁVEL DO GÊNERO NO BRASIL, segundo Kerber et al. (2011) — antes só havia registros pleistocênicos na Argentina e no Uruguai. Amplia a distribuição paleobiogeográfica do táxon. Coordenada aproximada: a fonte delimita o trecho fossilífero por dois extremos em UTM, a cerca de 19 km um do outro ao longo do arroio; adotado o ponto médio, conferido por ponto-em-polígono contra a malha do IBGE (cai em Santa Vitória do Palmar). O extremo oeste publicado cai fora do polígono municipal — provavelmente dentro da Lagoa Mirim. Idades por ressonância de spin eletrônico em dentes fósseis situam a assembleia entre ~226 e ~34 mil anos AP, um intervalo longo demais para uma única fauna — o conjunto pode ser tempo-médio.",
