    observacoes: "ÚNICO PAREIASSAURO CONHECIDO DAS AMÉRICAS, e um dos mais antigos do mundo. O crânio-tipo tem 330 mm; o animal teria cerca de 1,2 m do focinho à cloaca e 0,6 m de altura na cintura escapular. Quatro indivíduos de estágios ontogenéticos diferentes — dois adultos e dois juvenis — foram achados numa área de menos de 100 m², o que os autores leem como indício de algum grau de comportamento social. A análise filogenética o recupera dentro dos 'pareiassauros anões' do Karoo sul-africano, sendo o membro mais antigo do grupo. Coordenada regional: a fonte publica mapa dos sítios mas não coordenadas — usada a sede municipal. Artigo em acesso aberto (CC BY).",
