    observacoes: "POSIÇÃO ESTRATIGRÁFICA EM DISPUTA — leia antes de citar. Descrito em 2001 como da Fm. Rio do Rasto, mas Cisneros et al. (2021) apontam que o sítio hoje expõe a Fm. Teresina segundo o mapeamento da CPRM, e que o contexto estratigráfico preciso nunca foi publicado. O táxon é um platiopossauro, grupo restrito ao intervalo Sakmariano–Wordiano, e nunca foi achado associado a pareiassauros ou dinocéfalos. Provavelmente vem de unidade mais baixa: Membro Serrinha da Fm. Rio do Rasto ou a própria Fm. Teresina. Segundo arquegossaurídeo descrito para o Permiano brasileiro, depois de Prionosuchus plummeri, da Bacia do Parnaíba. Coordenada regional: a fonte publica mapa dos sítios mas não coordenadas — usada a sede municipal. Artigo em acesso aberto (CC BY).",
