    observacoes: "Forma de transição entre répteis primitivos e Archosauriformes — o clado que engloba dinossauros, crocodilianos, aves e pterossauros. Viveu logo depois da extinção do Permo-Triássico, que eliminou cerca de 90% das espécies. O nome vem de Teyú Yaguá, uma das sete lendas guarani, representada como um lagarto de cabeça de cão. O esqueleto é o mais completo já recuperado na Fm. Sanga do Cabral. Foi achado a cerca de 5 m da base do afloramento 5, num nível rico em concreções calcárias, em associação direta com vértebras de arcossauromorfo, restos de Procolophon trigoniceps, temnospôndilos e ossos ainda não identificados. O Bica São Tomé é o afloramento mais produtivo da Fm. Sanga do Cabral: já rendeu mais de duzentos espécimes e é a única localidade da unidade com material razoavelmente completo e articulado — em todas as outras o registro é fragmentário e retrabalhado. Coordenada publicada na descrição de Teyujagua paradoxa (29°36'56\\\"S, 55°03'10\\\"W) e conferida por ponto-em-polígono contra a malha do IBGE: cai em São Francisco de Assis. A localidade é composta por cinco afloramentos.",
