    observacoes: "REGISTRO FRÁGIL quanto à referência: o DOI da descrição original em PLOS ONE não foi confirmado nas fontes consultadas e não foi deduzido. Grupo-irmão dos tanistrofeídeos, os répteis de pescoço desproporcionalmente longo do Triássico Médio e Superior. A maioria dos tanistrofeídeos vem de depósitos marinhos do Hemisfério Norte; Elessaurus é continental e gondwânico, o que muda a leitura sobre a origem do grupo. O nome homenageia Elessar, nome élfico de Aragorn. É o pós-crânio mais completo da unidade depois de Teyujagua. O Bica São Tomé é o afloramento mais produtivo da Fm. Sanga do Cabral: já rendeu mais de duzentos espécimes e é a única localidade da unidade com material razoavelmente completo e articulado — em todas as outras o registro é fragmentário e retrabalhado. Coordenada publicada na descrição de Teyujagua paradoxa (29°36'56\\\"S, 55°03'10\\\"W) e conferida por ponto-em-polígono contra a malha do IBGE: cai em São Francisco de Assis. A localidade é composta por cinco afloramentos.",
