    observacoes: "REGISTRO FRÁGIL, E COM STATUS TAXONÔMICO EM DISPUTA. Descrito junto com Brasilodon quadrangularis, do mesmo sítio e da mesma biozona; trabalhos posteriores argumentam que os dois são a mesma espécie, sendo Brasilitherium sinônimo júnior de Brasilodon. Mantido como registro separado porque a literatura consultada ainda o trata como táxon próprio — conferir a posição atual antes de citar. É um dos táxons centrais na discussão sobre onde termina o cinodonte e começa o mamífero. Coordenada regional: a fonte nomeia o afloramento mas não publica coordenada — usada a sede municipal.",
