    tipo_fonte: "Artigo em periódico", doi: "10.22456/1807-9806.127863",
    observacoes: "Icnoespécie maior do icnogênero, atribuída a preguiças-terrícolas mylodontídeas. Túneis de 1,4 m de diâmetro são frequentes, e comprimentos originais foram estimados em mais de 50 m. As paleotocas são raras ou ausentes em planícies de inundação e em relevo montanhoso, e concentram-se em relevo ondulado e estável; é possível que cada colina da região tenha várias, isoladas ou em grupo, ao redor da base. As paleotocas da Região Metropolitana de Porto Alegre foram mapeadas sistematicamente ao longo de mais de uma década, numa área de mais de 10 mil km²: são mais de 400 túneis, a MAIOR DENSIDADE CONHECIDA DESSE TIPO DE ICNOFÓSSIL NO MUNDO. Larguras entre 0,5 e 3,0 m, alturas entre 0,5 e 2,0 m; mais de 80% estão preenchidos por sedimento e são classificados como crotovinas. Traços de escavação nas paredes e no teto são comuns, mas NENHUM FÓSSIL CORPORAL foi encontrado dentro deles — o produtor é inferido pelo tamanho e pelas marcas de garra, nunca observado diretamente. Coordenada regional: a fonte publica coordenadas de cada ocorrência numa tabela, mas o registro aqui agrega o conjunto do município — usada a sede municipal.",
    citacao_abnt: "FRANK, H. T. et al. Paleotocas gigantes na Região Metropolitana de Porto Alegre (estado do Rio Grande do Sul, Brasil). Pesquisas em Geociências, v. 50, n. 1, e127863, 2023.",
