    tipo_fonte: "Capítulo de sítio (SIGEP)", doi: "",
    observacoes: "REGISTRO SEM DETERMINAÇÃO ESPECÍFICA. Um dos poucos afloramentos onde os troncos aparecem INCLUSOS na rocha, e não rolados sobre a superfície — o que permite vinculá-los com segurança ao Arenito Mata. Na maioria dos sítios os lenhos ocorrem como associações densas roladas, o que dificulta a atribuição estratigráfica. Os troncos se orientam com o eixo maior transversal à direção de migração das barras arenosas de um sistema fluvial entrelaçado. A lignitafoflora do Arenito Mata é dominada por coníferas e NÃO tem pteridospermas do tipo Rhexoxylon, o que a torna mais recente que as floras Dicroidium e Rhexoxylon. SIGEP 009. O capítulo de sítio é uma fonte diferente de um artigo de descrição: consolida décadas de trabalho sobre a localidade e traz a lista taxonômica, mas não descreve espécimes novos. O selo de tipo de fonte informa isso. Uso não comercial permitido com citação. Capítulos do SIGEP não recebem DOI. Coordenada regional: o capítulo mapeia os sítios mas não publica coordenadas — usada a sede municipal.",
