    tipo_fonte: "Capítulo de sítio (SIGEP)", doi: "",
    observacoes: "REGISTRO DE ASSOCIAÇÃO, NÃO DE TÁXON. Preservada como impressões nos sedimentos da Fm. Santa Maria, com domínio de coníferas, pteridospermas e ginkgoales. Dicroidium é a folha que define a vegetação do Triássico gondwânico — a flora que sucede a Glossopteris depois da extinção do Permo-Triássico e antecede as coníferas do Arenito Mata. As ocorrências vegetais do Mesozóico gaúcho se distribuem numa faixa leste-oeste de cerca de 200 km na região central do estado; este registro cobre a associação como um todo, não um afloramento específico. SIGEP 009. O capítulo de sítio é uma fonte diferente de um artigo de descrição: consolida décadas de trabalho sobre a localidade e traz a lista taxonômica, mas não descreve espécimes novos. O selo de tipo de fonte informa isso. Uso não comercial permitido com citação. Capítulos do SIGEP não recebem DOI. Coordenada regional: o capítulo mapeia os sítios mas não publica coordenadas — usada a sede municipal.",
