    observacoes: "O SAUROPODOMORFO MAIS ANTIGO COM PESCOÇO ALONGADO — o plano corporal que define os sauropodomorfos pós-carnianos aparece aqui pela primeira vez. Descoberto em 2012. O sítio Wachholz é a localidade-tipo; em 2023 a espécie foi registrada também no sítio 'Boi da Guampa Torta', o que permitiu correlacionar os dois afloramentos. Como Macrocollum é filogeneticamente mais derivado que Pampadromaeus barberenai e Bagualosaurus agudoensis, ambos os sítios são mais jovens que o de Várzea do Agudo — um caso em que a filogenia serve de ferramenta bioestratigráfica. O segundo sítio não entrou no banco porque a fonte não informa o município. Coordenada regional: a fonte descreve o sítio mas não publica coordenada — usada a sede de Agudo.",
